  ('ritonavir', 'Ritonavir', 'Ritonavir', 'Antirretroviral inibidor da protease (IP) — potente inibidor do CYP3A4/P-gp', 'Antiretroviral protease inhibitor (PI) — potent CYP3A4/P-gp inhibitor', ARRAY['Norvir'], 'published', 83),
  ('atazanavir', 'Atazanavir', 'Atazanavir', 'Antirretroviral inibidor da protease (IP)', 'Antiretroviral protease inhibitor (PI)', ARRAY['Reyataz'], 'published', 84),
  ('nevirapina', 'Nevirapina', 'Nevirapine', 'Antirretroviral inibidor não nucleósido da transcriptase reversa (INNTR), indutor enzimático', 'Antiretroviral non-nucleoside reverse transcriptase inhibitor (NNRTI), enzyme inducer', ARRAY['Viramune'], 'published', 85),
  ('efavirenz', 'Efavirenz', 'Efavirenz', 'Antirretroviral INNTR, indutor enzimático', 'Antiretroviral NNRTI, enzyme inducer', ARRAY['Sustiva', 'Stocrin'], 'published', 86),
  ('zidovudina', 'Zidovudina', 'Zidovudine', 'Antirretroviral inibidor nucleósido da transcriptase reversa (INTR)', 'Antiretroviral nucleoside reverse transcriptase inhibitor (NRTI)', ARRAY['Retrovir', 'AZT'], 'published', 87),
  ('lamivudina', 'Lamivudina', 'Lamivudine', 'Antirretroviral INTR', 'Antiretroviral NRTI', ARRAY['Epivir', '3TC'], 'published', 88),
  ('praziquantel', 'Praziquantel', 'Praziquantel', 'Anti-helmíntico (céstodos e tremátodos)', 'Anthelmintic (cestodes and trematodes)', ARRAY['Biltricide'], 'published', 89),
  ('fenitoina', 'Fenitoína', 'Phenytoin', 'Antiepiléptico (bloqueador de canais de sódio)', 'Antiepileptic (sodium channel blocker)', ARRAY['Dilantin', 'Epanutin'], 'published', 90),
  ('valproato', 'Valproato', 'Valproic acid', 'Antiepiléptico (estabilizador de membrana; inibidor da GABA transaminase)', 'Antiepileptic (membrane stabilizer; GABA transaminase inhibitor)', ARRAY['Depakene', 'Depakote', 'ácido valpróico', 'valproato de sódio'], 'published', 91),
  ('lamotrigina', 'Lamotrigina', 'Lamotrigine', 'Antiepiléptico (bloqueador de canais de sódio)', 'Antiepileptic (sodium channel blocker)', ARRAY['Lamictal'], 'published', 92),
  ('fenobarbital', 'Fenobarbital', 'Phenobarbital', 'Barbitúrico antiepiléptico, indutor enzimático', 'Antiepileptic barbiturate, enzyme inducer', ARRAY['Gardenal', 'Luminal'], 'published', 93),
  ('litio', 'Lítio', 'Lithium', 'Estabilizador do humor (psicofármaco)', 'Mood stabilizer (psychotropic)', ARRAY['Priadel', 'Camcolit', 'carbonato de lítio'], 'published', 94),
  ('haloperidol', 'Haloperidol', 'Haloperidol', 'Antipsicótico (butirofenona)', 'Antipsychotic (butyrophenone)', ARRAY['Haldol'], 'published', 95),
  ('clozapina', 'Clozapina', 'Clozapine', 'Antipsicótico atípico', 'Atypical antipsychotic', ARRAY['Leponex', 'Clozaril'], 'published', 96),
  ('alprazolam', 'Alprazolam', 'Alprazolam', 'Benzodiazepina ansiolítica de curta duração', 'Short-acting anxiolytic benzodiazepine', ARRAY['Xanax'], 'published', 97);

INSERT INTO public.drug_interactions
  (drug_a_id, drug_b_id, severity, summary_pt, summary_en, mechanism_pt, mechanism_en,
   management_pt, management_en, monitoring_pt, monitoring_en, red_flags_pt, red_flags_en,
   source_pt, source_en, status, updated_at)
VALUES
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'ritonavir'),
        (SELECT id FROM public.drugs WHERE slug = 'warfarina')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'ritonavir'),
            (SELECT id FROM public.drugs WHERE slug = 'warfarina')),
   'moderate',
   'A associação de Ritonavir com Varfarina pode alterar de forma imprevisível o efeito anticoagulante da Varfarina, com risco de hemorragia ou de eventos trombóticos.',
'Combining Ritonavir with Warfarin can unpredictably alter the anticoagulant effect of Warfarin, posing a risk of bleeding or thrombotic events.',
'Ritonavir é um potente inibidor do CYP3A4 e da glicoproteína-P; a Varfarina é metabolizada sobretudo pelo CYP2C9. O efeito líquido sobre as concentrações de Varfarina é variável (aumento ou redução) entre doentes, exigindo monitorização.',
'Ritonavir is a potent inhibitor of CYP3A4 and P-glycoprotein; Warfarin is mainly metabolised by CYP2C9. The net effect on warfarin exposure is variable (increase or decrease) between patients, requiring monitoring.',
'Manter monitorização do INR sempre que o Ritonavir for iniciado, suspenso ou ajustado; titular a dose de Varfarina com base no INR. Preferir, se possível, anticoagulantes com farmacocinética mais previsível.',
'Maintain INR monitoring whenever Ritonavir is started, stopped or adjusted; titrate the Warfarin dose based on the INR. When possible, prefer anticoagulants with more predictable pharmacokinetics.',
'INR frequente no início e em cada alteração de dose; vigiar sinais de hemorragia (equimoses espontâneas, hemorragia gengival, hematúria) e sintomas de trombose.',
'Frequent INR at start and at each dose change; watch for bleeding signs (spontaneous bruising, gum bleeding, haematuria) and thrombotic symptoms.',
'INR acima de 3,5 ou hemorragia ativa exigem suspensão ou ajuste imediato do anticoagulante.',
'INR above 3.5 or active bleeding requires immediate discontinuation or adjustment of the anticoagulant.',
'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ritonavir: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2849298e-de6e-47bb-8194-56e075b33fc3 ; rótulo aprovado Warfarina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
'DailyMed/FDA (NIH/NLM) — approved Ritonavir label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2849298e-de6e-47bb-8194-56e075b33fc3 ; approved Warfarin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)',
'published', '2026-08-04 12:00:00+00'),
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'ritonavir'),
        (SELECT id FROM public.drugs WHERE slug = 'sildenafil')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'ritonavir'),
            (SELECT id FROM public.drugs WHERE slug = 'sildenafil')),
   'moderate',
   'A associação de Ritonavir com Sildenafil aumenta de forma marcada as concentrações e os efeitos do Sildenafil, com risco acrescido de hipotensão e priapismo.',
'Combining Ritonavir with Sildenafil markedly increases Sildenafil concentrations and effects, with an increased risk of hypotension and priapism.',
'Ritonavir (inibidor do CYP3A4) reduz drasticamente o metabolismo de primeira passagem do Sildenafil, aumentando muito a sua exposição sistémica.',
'Ritonavir (a CYP3A4 inhibitor) markedly reduces first-pass metabolism of Sildenafil, greatly increasing its systemic exposure.',
'O Sildenafil para disfunção erétil deverá ser iniciado em dose baixa (máx. 25 mg em 48 h) com Ritonavir; para hipertensão pulmonar a combinação é contraindicada em muitos regimes.',
'Sildenafil for erectile dysfunction should be started low (max 25 mg every 48 h) with Ritonavir; for pulmonary hypertension the combination is contraindicated in many regimens.',
'Vigiar tensão arterial, sintomas de hipotensão ortostática e duração anormal de ereção.',
'Monitor blood pressure, orthostatic hypotension and abnormally prolonged erection.',
'Hipotensão sintomática grave ou ereção com duração superior a 4 horas exigem avaliação médica urgente.',
'Severe symptomatic hypotension or an erection lasting more than 4 hours requires urgent medical evaluation.',
'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ritonavir: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2849298e-de6e-47bb-8194-56e075b33fc3 ; rótulo aprovado Sildenafil: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=00ee09dd-2de0-4dc4-85f6-b51ed6eabd5b — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
'DailyMed/FDA (NIH/NLM) — approved Ritonavir label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2849298e-de6e-47bb-8194-56e075b33fc3 ; approved Sildenafil label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=00ee09dd-2de0-4dc4-85f6-b51ed6eabd5b — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)',
'published', '2026-08-04 12:00:00+00'),
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'ritonavir'),
        (SELECT id FROM public.drugs WHERE slug = 'atorvastatina')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'ritonavir'),
            (SELECT id FROM public.drugs WHERE slug = 'atorvastatina')),
   'moderate',
   'A associação de Ritonavir com Atorvastatina aumenta as concentrações de Atorvastatina, com risco acrescido de miopatia e rabdomiólise.',
'Combining Ritonavir with Atorvastatin increases Atorvastatin concentrations, with an increased risk of myopathy and rhabdomyolysis.',
'Ritonavir, ao inibir o CYP3A4, reduz o metabolismo da Atorvastatina (substrato do CYP3A4), elevando a sua exposição e o risco de toxicidade muscular.',
'By inhibiting CYP3A4, Ritonavir reduces the metabolism of Atorvastatin (a CYP3A4 substrate), raising its exposure and the risk of muscular toxicity.',
'Limitar a dose de Atorvastatina a 20 mg/dia durante o uso de Ritonavir, ou selecionar uma estatina menos dependente do CYP3A4 (por exemplo pravastatina).',
'Limit Atorvastatin to 20 mg/day during Ritonavir use, or choose a statin less dependent on CYP3A4 (e.g. pravastatin).',
'Vigiar sintomas musculares (mialgias, fraqueza, urina escura) e, se sintomático, doseamento da creatina quinase.',
'Watch for muscle symptoms (myalgia, weakness, dark urine) and, if symptomatic, check creatine kinase.',
'Mialgia intensa, fraqueza proximal ou urina acastanhada impõem suspensão da estatina e avaliação médica.',
'Severe myalgia, proximal weakness or brown urine require stopping the statin and medical evaluation.',
'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ritonavir: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2849298e-de6e-47bb-8194-56e075b33fc3 ; rótulo aprovado Atorvastatina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=86841382-4229-4e03-958e-3ac22639efd4 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
'DailyMed/FDA (NIH/NLM) — approved Ritonavir label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2849298e-de6e-47bb-8194-56e075b33fc3 ; approved Atorvastatin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=86841382-4229-4e03-958e-3ac22639efd4 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)',
'published', '2026-08-04 12:00:00+00'),
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'ritonavir'),
        (SELECT id FROM public.drugs WHERE slug = 'carbamazepina')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'ritonavir'),
            (SELECT id FROM public.drugs WHERE slug = 'carbamazepina')),
   'moderate',
   'A associação de Ritonavir com Carbamazepina aumenta as concentrações e a toxicidade da Carbamazepina, exigindo ajuste de dose e monitorização.',
'Combining Ritonavir with Carbamazepine increases Carbamazepine concentrations and toxicity, requiring dose adjustment and monitoring.',
'Ritonavir inibe o CYP3A4, principal via de metabolismo da Carbamazepina, reduzindo a sua clearance e aumentando o risco de efeitos adversos (neurológicos, hematológicos).',
'Ritonavir inhibits CYP3A4, the main metabolic pathway of Carbamazepine, lowering its clearance and increasing the risk of adverse effects (neurological, haematological).',
'Reduzir a dose de Carbamazepina conforme necessário e, se disponível, monitorizar as concentrações séricas; considerar antiepiléptico alternativo.',
'Reduce the Carbamazepine dose as needed and, if available, monitor serum concentrations; consider an alternative antiepileptic.',
'Vigiar sinais de toxicidade da Carbamazepina: diplopia, ataxia, sonolência, náuseas, hiponatremia.',
'Watch for signs of Carbamazepine toxicity: diplopia, ataxia, drowsiness, nausea, hyponatraemia.',
'Sonolência marcada, ataxia ou diplopia requerem suspensão e reavaliação do esquema.',
'Marked drowsiness, ataxia or diplopia require discontinuation and reassessment of the regimen.',
'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ritonavir: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2849298e-de6e-47bb-8194-56e075b33fc3 ; rótulo aprovado Carbamazepina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9f3d91cd-a959-4e07-a51b-8a4e9ba9ece2 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
'DailyMed/FDA (NIH/NLM) — approved Ritonavir label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2849298e-de6e-47bb-8194-56e075b33fc3 ; approved Carbamazepine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9f3d91cd-a959-4e07-a51b-8a4e9ba9ece2 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)',
'published', '2026-08-04 12:00:00+00'),
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'atazanavir'),
        (SELECT id FROM public.drugs WHERE slug = 'omeprazol')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'atazanavir'),
            (SELECT id FROM public.drugs WHERE slug = 'omeprazol')),
   'moderate',
   'A associação de Atazanavir com Omeprazol reduz substancialmente as concentrações de Atazanavir, com risco de falência virológica.',
'Combining Atazanavir with Omeprazole substantially reduces Atazanavir concentrations, with a risk of virological failure.',
'Os inibidores da bomba de protões, como o Omeprazol, elevam o pH gástrico, reduzindo a absorção do Atazanavir e diminuindo a sua exposição.',
'Proton pump inhibitors such as Omeprazole raise gastric pH, reducing Atazanavir absorption and lowering its exposure.',
'Evitar a associação quando possível; se inevitável, preferir antagonistas dos recetores H2 e/ou separar as administrações; não usar IBP com doses baixas de Atazanavir.',
'Avoid the combination when possible; if unavoidable, prefer H2-receptor antagonists and/or separate dosing times; do not use a PPI with low doses of Atazanavir.',
'Monitorizar a carga viral e, se disponível, a litemia/imunidade; reavaliar quando da introdução ou suspensão do Omeprazol.',
'Monitor viral load and, if available, CD4; reassess when Omeprazole is started or stopped.',
'Carga viral detetável ou sinais de falência terapêutica após início do Omeprazol exigem reavaliação do esquema antirretroviral.',
'Detectable viral load or signs of therapeutic failure after starting Omeprazole require reassessment of the antiretroviral regimen.',
'DailyMed/FDA (NIH/NLM) — rótulo aprovado Atazanavir: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=165cff62-b284-4a27-a65d-9ec8a5bfcdd8 ; rótulo aprovado Omeprazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=37291cab-e350-d8e3-e063-6294a90a9cb1 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
'DailyMed/FDA (NIH/NLM) — approved Atazanavir label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=165cff62-b284-4a27-a65d-9ec8a5bfcdd8 ; approved Omeprazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=37291cab-e350-d8e3-e063-6294a90a9cb1 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)',
'published', '2026-08-04 12:00:00+00'),
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'atazanavir'),
        (SELECT id FROM public.drugs WHERE slug = 'antiacidos')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'atazanavir'),
            (SELECT id FROM public.drugs WHERE slug = 'antiacidos')),
   'moderate',
   'A associação de Atazanavir com Antiácidos reduz a absorção do Atazanavir, com risco de diminuição da sua eficácia.',
'Combining Atazanavir with Antacids reduces Atazanavir absorption, with a risk of reduced efficacy.',
'Os antiácidos (hidróxido de alumínio/magnésio) elevam o pH gástrico e podem quelar o Atazanavir, diminuindo a sua biodisponibilidade.',
'Antacids (aluminium/magnesium hydroxide) raise gastric pH and may chelate Atazanavir, lowering its bioavailability.',
'Separar a administração: tomar os antiácidos pelo menos 2 horas antes ou depois do Atazanavir.',
'Separate administration: take antacids at least 2 hours before or after Atazanavir.',
'Monitorizar a resposta virológica ao regime antirretroviral.',
'Monitor the virological response to the antiretroviral regimen.',
'Carga viral detetável após uso regular de antiácidos exige reavaliação do esquema.',
'Detectable viral load with regular antacid use requires reassessment of the regimen.',
'DailyMed/FDA (NIH/NLM) — rótulo aprovado Atazanavir: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=165cff62-b284-4a27-a65d-9ec8a5bfcdd8 ; rótulo aprovado Antiácidos: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c72f0736-ee20-45b4-baf0-b80f1e3fa9cb — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
'DailyMed/FDA (NIH/NLM) — approved Atazanavir label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=165cff62-b284-4a27-a65d-9ec8a5bfcdd8 ; approved Antacids label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c72f0736-ee20-45b4-baf0-b80f1e3fa9cb — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)',
'published', '2026-08-04 12:00:00+00'),
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'atazanavir'),
        (SELECT id FROM public.drugs WHERE slug = 'warfarina')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'atazanavir'),
            (SELECT id FROM public.drugs WHERE slug = 'warfarina')),
   'moderate',
   'A associação de Atazanavir com Varfarina pode potenciar o efeito anticoagulante e aumentar o risco de hemorragia grave.',
'Combining Atazanavir with Warfarin may potentiate the anticoagulant effect and increase the risk of serious bleeding.',
